/// resilient-clients.mdx line 1739: "Slow consumers", block 1.
mod slow_consumers_1 {
    #![allow(dead_code, unused_variables, unused_assignments, unreachable_code, unreachable_pub)]
    use super::prelude::*;

    async fn slow_work(_: Event) -> Result<()> { Ok(()) }

    async fn example(seeds: Vec<Seed>, mut config: ClientConfig) -> Result<()> {
        // A reader with bursty processing asks for more room.
        config.broker_sub_queue_capacity = Some(4096);
        config.client_sub_queue_capacity = 8192;
        let client = Arc::new(
            ClusterClient::connect_seeds(&seeds, "felix.example.com", config, ReconnectPolicy::default())
                .await?,
        );

        let mut subscription = client.subscribe("acme", "prod", "webhooks").await?;

        // Hand slow work to a task over a bounded channel instead of doing it in the
        // read loop, where it holds up the next event.
        let (queued, mut work) = tokio::sync::mpsc::channel::<Event>(100);
        let worker = tokio::spawn(async move {
            while let Some(event) = work.recv().await {
                slow_work(event).await?;
            }
            anyhow::Ok(())
        });
        while let Some(event) = subscription.next_event().await? {
            if queued.send(event).await.is_err() {
                break; // the worker stopped; its result below says why
            }
        }
        // Closing the channel lets the worker drain what is queued and finish.
        drop(queued);
        worker.await??;
        Ok(())
    }
}

/// resilient-clients.mdx line 1929: "Consumer groups under failure", block 1.
mod consumer_groups_under_failure_1 {
    #![allow(dead_code, unused_variables, unused_assignments, unreachable_code, unreachable_pub)]
    use super::prelude::*;

    async fn charge(_: &[u8], _: u32) -> Result<()> { Ok(()) }

    async fn example(client: &ClusterClient, stop: &std::sync::atomic::AtomicBool) -> Result<()> {
        use felix_client::{BrokerError, ErrorCode, GroupMember};

        fn is_stale_claim(err: &anyhow::Error) -> bool {
            err.downcast_ref::<BrokerError>()
                .is_some_and(|refusal| refusal.code == ErrorCode::StaleClaim)
        }

        // A claim that lapsed means the record belongs to the group again.
        fn tolerate_stale(result: Result<()>) -> Result<()> {
            match result {
                Err(err) if is_stale_claim(&err) => {
                    tracing::warn!("claim lapsed; the record will be delivered again");
                    Ok(())
                }
                other => other,
            }
        }

        let member = GroupMember { consumer: "billing-worker-1".into(), reclaim: true };
        while !stop.load(std::sync::atomic::Ordering::Relaxed) {
            let records = client
                .group_poll_as("acme", "prod", "orders", 0, "billing", Some(&member), 16, Duration::from_secs(5))
                .await?;
            for record in records {
                // Ask for time before the slow step.
                if let Err(err) = client
                    .group_extend("acme", "prod", "orders", 0, "billing", &record, Duration::from_secs(60))
                    .await
                {
                    if is_stale_claim(&err) {
                        continue; // someone else has it now
                    }
                    return Err(err);
                }
                match charge(&record.payload, record.attempts).await {
                    Ok(()) => tolerate_stale(
                        client.group_ack("acme", "prod", "orders", 0, "billing", record.offset).await,
                    )?,
                    Err(err) => {
                        tracing::warn!(offset = record.offset, "charge failed: {err:#}");
                        // Back off before the retry instead of redelivering at once.
                        tolerate_stale(
                            client
                                .group_nack_after(
                                    "acme", "prod", "orders", 0, "billing", &record, Duration::from_secs(30),
                                )
                                .await,
                        )?;
                    }
                }
            }
        }
        Ok(())
    }
}

